def parse(line):
    state, key, val, out = 'KEY', '', '', {}
    for ch in line:
        if state == 'KEY':
            if ch == '=': state = 'VALUE'
            elif ch == '#': state = 'COMMENT'
            else: key += ch
        elif state == 'VALUE':
            if ch == '#': state = 'COMMENT'
            else: val += ch
        elif state == 'COMMENT':
