class History:
    def __init__(self, checkpoint_every=3):
        self.snaps = {0: ''}
        self.deltas = []
        self.every = checkpoint_every
    def record(self, delta, state):
        self.deltas.append(delta)
        if len(self.deltas) % self.every == 0:
            self.snaps[len(self.deltas)] = state
    def state_at(self, n, apply_delta):
        base = max(k for k in self.snaps if k <= n)
        state = self.snaps[base]
        for d in self.deltas[base:n]:
            state = apply_delta(state, d)
        return state
