class Store:
    def __init__(self): self.db = {}; self.cache = {}; self.dirty = set()
    def write_through(self, k, v):
        self.cache[k] = v; self.db[k] = v
    def write_back(self, k, v):
        self.cache[k] = v; self.dirty.add(k)
    def flush(self):
        for k in self.dirty: self.db[k] = self.cache[k]
        self.dirty.clear()
