import zlib, json
def frame(payload):
    body = json.dumps(payload)
    return f'{zlib.crc32(body.encode())}:{body}'
def recover(lines):
    state = {}
    for line in lines:
        try:
            crc, body = line.split(':', 1)
            if zlib.crc32(body.encode()) != int(crc): break
            k, v = json.loads(body)
            state[k] = v
        except Exception:
            break
    return state
