class LWW:
    def __init__(self): self.entry = None
    def set(self, value, ts, node):
        cand = (ts, node, value)
        if self.entry is None or (ts, node) > (self.entry[0], self.entry[1]):
            self.entry = cand
    def merge(self, other):
        if other.entry: self.set(other.entry[2], other.entry[0], other.entry[1])
writes = [(1, 'A', 'alpha'), (1, 'B', 'beta'), (2, 'A', 'gamma')]
def run(order):
    a, b = LWW(), LWW()
    for who, (ts, node, val) in order:
        (a if who == 'A' else b).set(val, ts, node)
    a.merge(b); b.merge(a); a.merge(b)
    return a.entry, b.entry
orders = []
for perm in itertools.permutations(writes):
    for assign in itertools.product('AB', repeat=3):
        orders.append(list(zip(assign, perm)))
results = {run(o) for o in orders}
print('interleavings tested:', len(orders))
print('distinct final states:', len(results))
print('converged value:', results.pop())

class Task:
    def __init__(self, tid):
        self.tid = tid
        self.title = ('', 0, '')
        self.done = False
        self.tombstone = (False, 0, '')
    def rename(self, title, ts, node):
        if (ts, node) > (self.title[1], self.title[2]): self.title = (title, ts, node)
    def complete(self): self.done = True
    def delete(self, ts, node):
        if (ts, node) > (self.tombstone[1], self.tombstone[2]): self.tombstone = (True, ts, node)
    def merge(self, o):
        self.rename(o.title[0], o.title[1], o.title[2])
        self.done = self.done or o.done
        if (o.tombstone[1], o.tombstone[2]) > (self.tombstone[1], self.tombstone[2]): self.tombstone = o.tombstone
    def visible(self): return not self.tombstone[0]
phone, tablet = Task('t1'), Task('t1')
phone.rename('buy milk', 1, 'P'); tablet.merge(phone); phone.merge(tablet)
phone.rename('buy oat milk', 3, 'P'); phone.complete()
tablet.rename('buy milk!', 2, 'T'); tablet.delete(4, 'T')
phone.merge(tablet); tablet.merge(phone)
print('converged:', (phone.title, phone.done, phone.tombstone) == (tablet.title, tablet.done, tablet.tombstone))
print('title:', phone.title[0], '| done:', phone.done, '| visible:', phone.visible())
